import type { ComponentProps } from "@types";
import type { CSSObject } from "@emotion/react";

import React from "react";

export enum PaginationAriaLabels {
  PageIndexButton = "pageIndexButton",
}

export type PageItem = { type: "page" | "ellipsis"; value?: number };
export interface PaginationContextType {
  items: PageItem[];
  selectedIndex: number;
  selectIndex: (index: number) => void;
  start: number;
  finish: number;
  spread: number;
}

// Props for the pagination component
export type PaginationProps = ComponentProps & {
  start?: number;
  finish?: number;
  spread?: number;
  selected?: number;
  onSelectedChange?: (selected: number) => void;
  styleSlots?: {
    root?: CSSObject;
    ellipsis?: CSSObject;
    prevButton?: CSSObject;
    nextButton?: CSSObject;
    prevButtonDisabled?: CSSObject;
    nextButtonDisabled?: CSSObject;
    pageButton?: CSSObject;
    pageButtonSelected?: CSSObject;
  };
  children?: React.ReactNode;
};

export interface PaginationPrevProps extends React.HTMLAttributes<HTMLElement> {
  className?: string;
  children?: React.ReactNode;
}

export interface PaginationNextProps extends React.HTMLAttributes<HTMLElement> {
  className?: string;
  children?: React.ReactNode;
}

export interface PaginationEllipsisProps extends React.HTMLAttributes<HTMLElement> {
  className?: string;
}

export interface PaginationItemsProps {
  render?: (item: PageItem, index: number) => React.ReactNode;
  getItemAriaLabel?: (label: PaginationAriaLabels, page?: number) => string | undefined;
}
